import json,re
d=json.load(open('current-state.json'))
print(type(d), list(d.keys())[:40] if isinstance(d,dict) else len(d))
s=json.dumps(d)
print(len(s))
print('orca count', len(re.findall('orca',s,re.I)))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): yield from walk(v,p+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): yield from walk(v,p+'/'+str(i))
    elif isinstance(o,str):
        if 'three pieces overlap' in o or re.search('orca',o,re.I):
            yield p,o
for p,v in walk(d):
    # print only context around each match
    ms=[m.start() for m in re.finditer('orca',v,re.I)]
    print('PATH',p,'len',len(v),'matches',len(ms))
    for m in ms[:6]:
        print('   ...',v[max(0,m-110):m+130].replace('\n',' '))
EOF

