55	json input_items(const TurnTranscript& transcript)
56	{
57	    json input = json::array();
58	    for (const RecordItem& item : transcript.items) {
59	        switch (item.kind) {
60	        case RecordItem::Kind::User: {
61	            json content = json::array();
62	            for (const RecordPart& part : item.parts)
63	                content.push_back(input_part(part));
64	            input.push_back(json{{"role", "user"}, {"content", std::move(content)}});
65	            break;
66	        }
67	        // An app note or a fired skill, in the app's voice.
68	        case RecordItem::Kind::Operator: input.push_back(json{{"role", "developer"}, {"content", item.text}}); break;
69	        case RecordItem::Kind::Assistant:
70	            // The response's own items, reasoning included, exactly as sent.
71	            input.insert(input.end(), item.output.begin(), item.output.end());
72	            break;
73	        case RecordItem::Kind::Results:
74	            for (const RecordResult& result : item.results)
75	                input.push_back(json{{"type", "function_call_output"}, {"call_id", result.call_id}, {"output", result.output_json}});
76	            // A function result is text only; the pictures follow the results
77	            // as image inputs.
78	            for (const RecordResult& result : item.results)
79	                if (result.image)
80	                    input.push_back(json{{"role", "user"},
81	                                         {"content", json::array({text_part("The image returned by call " + result.call_id + "."),
82	                                                                  input_part(*result.image)})}});
83	            break;
84	        }
85	    }
86	    return input;
87	}
