91	ProviderRequest ResponsesCodec::build(const TurnTranscript& transcript, const ProviderProfile& profile, RequestKind kind) const
92	{
93	    ProviderRequest request;
94	    request.headers.push_back({"Idempotency-Key", transcript.request_id + "-request-" + std::to_string(transcript.request_sequence)});
95	    json input = input_items(transcript);
96	    if (kind == RequestKind::ConversationTitle) {
97	        request.body = json{{"model", profile.model}, {"store", false}, {"stream", true},
98	                            {"instructions", kConversationTitleInstructions}, {"input", std::move(input)}};
99	        return request;
100	    }
101	    // Every session's instructions are written by its page and arrive in the
102	    // session profile, the project assistant's included
103	    // (AgentUI/src/projectInstructions.ts); this codec adds no words of its
104	    // own. The text is the same on every request of a conversation, which the
105	    // provider's prompt cache depends on. A response may hold several calls:
106	    // a read and the change it does not depend on belong in one step, and
107	    // some models send several whatever this says (ProviderAgent runs them
108	    // all, in order).
109	    request.body = json{{"model", profile.model}, {"store", false}, {"stream", true}, {"parallel_tool_calls", true},
110	                        {"instructions", transcript.instructions}, {"tools", tools_json(transcript.tools)}, {"input", std::move(input)}};
111	    // OpenAI and OpenRouter read the same field.
112	    if (!profile.effort.empty())
113	        request.body["reasoning"] = json{{"effort", profile.effort}};
114	    // Every chat opens with the same instructions and tools, which is what
115	    // the provider picks a cache machine by; the key keeps each chat on its
116	    // own. JusPrin's gateway refuses a field it does not list, and does not
117	    // list this one yet.
118	    if (!transcript.chat_key.empty() && !profile.account_sign_in)
119	        request.body["prompt_cache_key"] = transcript.chat_key;
120	    return request;
121	}
