123	std::vector<StreamEvent> ResponsesCodec::parse(const std::string& payload)
124	{
125	    std::vector<StreamEvent> events;
126	    const auto               push = [&events](StreamEvent::Kind kind) -> StreamEvent& {
127	        events.push_back(StreamEvent{});
128	        events.back().kind = kind;
129	        return events.back();
130	    };
131	    const json event = json::parse(payload, nullptr, false);
132	    if (!event.is_object()) {
133	        push(StreamEvent::Kind::Failed).error = {"malformed_response", "The Agent service returned an unreadable streaming response.", false};
134	        return events;
135	    }
136	    const std::string type = event.value("type", "");
137	    if (type == "response.output_text.delta" && event.contains("delta") && event["delta"].is_string()) {
138	        push(StreamEvent::Kind::TextDelta).text = event["delta"].get<std::string>();
139	    } else if (type == "response.completed" && event.contains("response")) {
140	        if (m_completed)
141	            return events;
142	        m_completed = true;
143	        const json& response = event["response"];
144	        if (!response.is_object() || !response.contains("output") || !response["output"].is_array()) {
145	            push(StreamEvent::Kind::Failed).error = {"malformed_response", "The Agent service response did not contain valid output.", false};
146	            return events;
147	        }
148	        StreamEvent& complete = push(StreamEvent::Kind::TurnComplete);
149	        complete.assistant_turn = response["output"];
150	        for (const json& item : complete.assistant_turn)
151	            if (item.is_object() && item.value("type", "") == "function_call")
152	                complete.calls.push_back({item.value("call_id", ""), item.value("name", ""), item.value("arguments", "{}")});
153	        if (response.contains("usage") && response["usage"].is_object()) {
154	            const json& usage = response["usage"];
155	            AgentUsage   reported;
156	            reported.input  = usage.value("input_tokens", std::uint64_t{0});
157	            reported.output = usage.value("output_tokens", std::uint64_t{0});
158	            reported.total  = usage.value("total_tokens", std::uint64_t{0});
159	            if (usage.contains("input_tokens_details") && usage["input_tokens_details"].is_object())
160	                reported.cached_input = usage["input_tokens_details"].value("cached_tokens", std::uint64_t{0});
161	            complete.usage = reported;
162	        }
163	    } else if (type == "response.incomplete") {
164	        push(StreamEvent::Kind::Incomplete);
165	    } else if (type == "response.failed" || type == "error") {
166	        push(StreamEvent::Kind::Failed).error = {"agent_service_error", "The Agent service could not complete the response.", true};
167	    }
168	    return events;
169	}
