37	json workspace_json(const AgentRequest& request)
38	{
39	    const Workspace::WorkspaceSnapshot& workspace = request.workspace;
40	    json plates = json::array();
41	    for (const auto& plate : workspace.plates) {
42	        json objects = json::array();
43	        for (const auto& object : plate.objects)
44	            objects.push_back(json{{"id", std::to_string(object.id.value())}, {"name", object.name},
45	                                   {"instances", object.instances.size()}});
46	        json entry{{"id", std::to_string(plate.id.value())}, {"name", plate.name},
47	                   {"active", plate.active}, {"sliced", plate.sliced}, {"objects", std::move(objects)}};
48	        // In printer_setup's name and plate_layout's values, so a filament
49	        // the plate cannot take is visible before anything is sliced.
50	        if (!plate.bed_type.empty())
51	            entry["plateType"] = plate.bed_type;
52	        // Why its last slice did not succeed, whoever asked for that slice.
53	        if (plate.slice_failure)
54	            entry["sliceFailure"] = slice_failure_result(*plate.slice_failure);
55	        // What its current slice warned about, whoever sliced it.
56	        if (plate.slice_warnings)
57	            entry["sliceWarnings"] = slice_warnings_result(*plate.slice_warnings);
58	        // A calibration test's steps, while the plate's print holds them.
59	        if (plate.calibration)
60	            entry["calibration"] = calibration_steps_result(*plate.calibration);
61	        plates.push_back(std::move(entry));
62	    }
63	    json selected = json::array();
64	    for (const auto id : workspace.selected_objects)
65	        selected.push_back(std::to_string(id.value()));
66	    json result{{"sessionId", std::to_string(workspace.session.value())},
67	                {"revision", workspace.revision},
68	                {"projectName", workspace.setup.project_name},
69	                {"printerPreset", workspace.setup.printer_preset},
70	                {"filamentPreset", workspace.setup.filament_preset},
71	                {"selectedObjectIds", std::move(selected)},
72	                {"plates", std::move(plates)}};
73	    if (!workspace.setup.process_preset.empty())
74	        result["processPreset"] = workspace.setup.process_preset;
75	    // The model's own notes: the purpose it recorded, and the plan in the
76	    // shape workspace_inspect's plan section returns, less its timestamp. On
77	    // the next turn it reads what it recorded without spending a call on it.
78	    json intent = json::object();
79	    if (!request.setup_title.empty())
80	        intent["purpose"] = request.setup_title;
81	    if (request.setup_unchecked_change)
82	        intent["setupUncheckedChange"] = true;
83	    if (!intent.empty())
84	        result["intent"] = std::move(intent);
85	    const json full_plan = plan_section_result(request.plan);
86	    json plan{{"headline", full_plan["headline"]}, {"decisions", full_plan["decisions"]},
87	              {"unverified", full_plan["unverified"]}, {"truncated", full_plan["truncated"]}};
88	    drop_empty(plan);
89	    // Whether the plan still holds, and the edit that put it in doubt.
90	    if (!plan.empty()) {
91	        plan["validity"] = full_plan["validity"];
92	        if (!request.plan.invalidated_by.empty())
93	            plan["invalidatedBy"] = full_plan["invalidatedBy"];
94	        result["plan"] = std::move(plan);
95	    }
96	    // What left the project and what the printers reported, newest first,
97	    // for when the person says how a print went. A print with no finish may
98	    // still be running or may have stopped: nothing records which.
99	    json history = json::array();
100	    for (const AgentRequest::GcodeHistoryEntry& entry : request.gcode_history) {
101	        const GcodeRecord& record = entry.record;
102	        json exports = json::array(), sends = json::array(), prints = json::array();
103	        for (const GcodeDestination& destination : record.destinations) {
104	            if (destination.kind == GcodeDestination::Kind::Export)
105	                exports.push_back(json{{"at", destination.at},
106	                                       {"file", std::filesystem::u8path(destination.path).filename().u8string()}});
107	            else
108	                sends.push_back(json{{"at", destination.at}, {"printer", destination.printer_name},
109	                                     {"startRequested", destination.start_requested}});
110	        }
111	        for (const GcodePrint& print : record.prints) {
112	            json item{{"printer", print.printer_name}, {"startedAt", print.started_at}};
113	            if (!print.finished_at.empty())
114	                item["finishedAt"] = print.finished_at;
115	            prints.push_back(std::move(item));
116	        }
117	        json item{{"gcode", record.hash.substr(0, 8)},
118	                  {"firstLeftAt", record.created_at},
119	                  {"plate", record.plate_name},
120	                  {"printerPreset", record.printer},
121	                  {"filamentPreset", record.material},
122	                  {"processPreset", record.process},
123	                  {"sameInputsAsNow", entry.same_inputs_as_now},
124	                  {"exports", std::move(exports)},
125	                  {"sends", std::move(sends)},
126	                  {"prints", std::move(prints)}};
127	        if (record.statistics.print_time_seconds > 0.0)
128	            item["estimatedSeconds"] = record.statistics.print_time_seconds;
129	        if (record.statistics.material_grams > 0.0)
130	            item["estimatedGrams"] = record.statistics.material_grams;
131	        drop_empty(item);
132	        history.push_back(std::move(item));
133	    }
134	    if (!history.empty())
135	        result["printHistory"] = std::move(history);
136	    return result;
137	}
