139	bool available_in_app(const ToolDefinition& definition, bool allow_import, bool skills_listed,
140	                      const std::vector<std::string>& session_tools)
141	{
142	    // A session with a subject of its own offers exactly the tools it names,
143	    // and those may be its own rather than the app's.
144	    if (!session_tools.empty())
145	        return std::find(session_tools.begin(), session_tools.end(), definition.name) != session_tools.end() &&
146	               (has_exposure(definition.exposure, ToolExposure::InApp) || has_exposure(definition.exposure, ToolExposure::Printer));
147	    return has_exposure(definition.exposure, ToolExposure::InApp) &&
148	           (definition.availability == ToolAvailability::Always ||
149	            (definition.availability == ToolAvailability::ImportableAttachment && allow_import) ||
150	            (definition.availability == ToolAvailability::SkillIndex && skills_listed));
151	}
