153	// The tools this turn offers, in the registry's order.
154	std::vector<OfferedTool> offered_tools(const AgentRequest& request)
155	{
156	    const bool allow_import = std::any_of(request.attachments.begin(), request.attachments.end(),
157	                                          [](const AgentAttachmentContext& attachment) { return attachment.importable; });
158	    std::vector<OfferedTool> tools;
159	    for (const ToolDefinition& definition : ToolRegistry::instance().definitions()) {
160	        if (!available_in_app(definition, allow_import, !request.skill_index.empty(), request.session.tool_names))
161	            continue;
162	        // skill_read carries the list it reads from, as one line per skill.
163	        std::string description = definition.description;
164	        if (definition.handler == ToolHandler::SkillRead) {
165	            description += "\n\nSkills:";
166	            for (const AgentSkill& skill : request.skill_index)
167	                description += "\n- " + skill.name + ": " + skill.description;
168	        }
169	        tools.push_back(OfferedTool{&definition, std::move(description)});
170	    }
171	    return tools;
172	}
