174	// The skills to send with one request. A skill that yields to another fired
175	// for the same request is left out.
176	std::vector<AgentSkillUse> skills_to_send(const std::vector<AgentSkillUse>& skills)
177	{
178	    std::vector<AgentSkillUse> sent;
179	    for (const AgentSkillUse& skill : skills) {
180	        const bool yields = std::any_of(skills.begin(), skills.end(), [&skill](const AgentSkillUse& other) {
181	            return std::find(skill.yields_to.begin(), skill.yields_to.end(), other.trigger) != skill.yields_to.end();
182	        });
183	        if (!yields)
184	            sent.push_back(skill);
185	    }
186	    return sent;
187	}
