215	void ProviderAgent::begin_transcript(const AgentRequest& request)
216	{
217	    m_transcript = TurnTranscript{};
218	    m_transcript.request_id   = request.request_id;
219	    m_transcript.instructions = request.session.instructions;
220	    m_transcript.opening      = request.conversation;
221	    if (request.purpose == AgentRequest::Purpose::ConversationTitle)
222	        return;
223	    m_transcript.tools = offered_tools(request);
224	    m_transcript.opening_once = skills_to_send(request.skills);
225	    // A turn the app started, after one of its own notes: nothing was said,
226	    // and an empty user message would read as the person saying nothing.
227	    if (request.user_text.empty() && request.issue_context.empty() && request.attachments.empty() &&
228	        !request.session.include_workspace)
229	        return;
230	
231	    // One part per kind of content: the person's words exactly as typed, then
232	    // the app's data, each in its own tag, then the attachments.
233	    std::vector<TurnContentPart>& content = m_transcript.user_content;
234	    const auto text = [&content](std::string value) {
235	        TurnContentPart part;
236	        part.text = std::move(value);
237	        content.push_back(std::move(part));
238	    };
239	    if (!request.user_text.empty())
240	        text(request.user_text);
241	    if (!request.issue_context.empty())
242	        text(tagged_block("print_issue", request.issue_context));
243	    if (request.session.include_workspace)
244	        text(tagged_block("workspace", workspace_json(request).dump()));
245	    std::ostringstream attachments;
246	    for (const auto& attachment : request.attachments) {
247	        if (attachments.tellp() > 0)
248	            attachments << "\n";
249	        attachments << "Attachment " << attachment.id << ": " << attachment.name << " [" << attachment.kind << "]";
250	        if (!attachment.summary.empty())
251	            attachments << " — " << attachment.summary;
252	        if (!attachment.text.empty())
253	            attachments << "\n<attachment id=\"" << attachment.id << "\">\n" << attachment.text << "\n</attachment>";
254	    }
255	    if (attachments.tellp() > 0)
256	        text(attachments.str());
257	    for (const auto& attachment : request.attachments) {
258	        if (attachment.bytes.empty())
259	            continue;
260	        TurnContentPart part;
261	        part.mime   = attachment.mime.empty() ? "application/octet-stream" : attachment.mime;
262	        part.base64 = base64_encode(attachment.bytes);
263	        if (attachment.kind == "image") {
264	            part.kind = TurnContentPart::Kind::Image;
265	        } else if (attachment.kind == "pdf") {
266	            part.kind     = TurnContentPart::Kind::Pdf;
267	            part.filename = attachment.name;
268	        } else {
269	            continue;
270	        }
271	        content.push_back(std::move(part));
272	    }
273	}
