#!/usr/bin/env python3
"""Rebuild the request behind message m-27 of chat c-2 from the saved project,
following the source of build 953eddb355, and optionally send it.

  replay_orca_request.py build
  replay_orca_request.py send <runs>     (needs OPENAI_API_KEY, ANTHROPIC_API_KEY)
"""
import concurrent.futures
import json
import os
import pathlib
import re
import sys
import time
import urllib.error
import urllib.request

REPO = pathlib.Path("/Users/kenneth/Projects/JusPrin")
PROJECT = pathlib.Path(os.path.expanduser(
    "~/Library/Application Support/JusPrin2/jusprin/projects/p-695f6cbd7c153ebf-6d45f33818b087a0"))
OUT = pathlib.Path(__file__).parent
OPENAI_MODEL = "gpt-5.4-mini"  # the app's default on its OpenAI row
CLAUDE_MODEL = "claude-opus-5-5"  # the app's default on its Anthropic row


def dump(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def tagged_block(tag, text):
    return f"<{tag}>\n" + text.replace("</", "<\\/") + f"\n</{tag}>"


def tool_output(activity):
    return dump({"state": activity["state"], "result": json.loads(activity["result"])})


def workspace_block(conversation):
    summary = conversation["resumeCheckpoint"]["summary"]
    plate = summary["plates"][0]
    plan = conversation["plan"]
    return tagged_block("workspace", dump({
        "sessionId": summary["sessionId"],
        "revision": summary["revision"],
        "projectName": summary["projectName"],
        "printerPreset": summary["printer"]["preset"],
        "filamentPreset": summary["printer"]["filament"],
        "processPreset": summary["printer"]["process"],
        "selectedObjectIds": [],
        "plates": [{
            "id": plate["id"], "name": plate["name"], "active": plate["active"], "sliced": plate["sliced"],
            "objects": [{"id": o["id"], "name": o["name"], "instances": o["instances"]} for o in plate["objects"]],
            "plateType": summary["setupIdentity"]["plateType"],
            "sliceWarnings": plate["sliceWarnings"],
        }],
        "plan": {"headline": plan["headline"], "decisions": plan["decisions"], "unverified": plan["assumptions"],
                 "validity": plan["validity"]},
    }))


def build():
    state = json.loads((PROJECT / "current-state.json").read_text())["state"]
    conversation = next(c for c in state["conversations"] if c["id"] == "c-2")
    activities = [a for a in state["toolActivities"] if a.get("callId")]
    calls = {}
    for activity in activities:
        calls.setdefault(activity["correlationId"], []).append(activity)

    # History: every message before the note that started this turn. A note
    # stays out of the model's context, and earlier user messages go without
    # their workspace block.
    items = []
    for message in conversation["messages"]:
        if message["id"] == "m-22":
            break
        if message["text"]:
            items.append({"role": message["role"], "content": message["text"]})
        for activity in calls.get(message["id"], []):
            items.append({"type": "function_call", "call_id": activity["callId"], "name": activity["tool"],
                          "arguments": activity["arguments"]})
            items.append({"type": "function_call_output", "call_id": activity["callId"], "output": tool_output(activity)})

    # This turn: the workspace on its own, then its two responses. slice_report
    # came alone; the three fit checks came together. DeepSeek's reasoning
    # items, if it returned any, were not saved, so they are missing here.
    items.append({"role": "user", "content": [{"type": "input_text", "text": workspace_block(conversation)}]})
    by_id = {a["actionId"]: a for a in activities}
    for step in (["t-12"], ["t-13", "t-14", "t-15"]):
        for action in step:
            a = by_id[action]
            items.append({"type": "function_call", "call_id": a["callId"], "name": a["tool"], "arguments": a["arguments"]})
        for action in step:
            a = by_id[action]
            items.append({"type": "function_call_output", "call_id": a["callId"], "output": tool_output(a)})

    tools = json.loads((REPO / "tests/project_prompt/project_tools.json").read_text())
    # At this build object_import was offered only with an importable attachment.
    tools = [t for t in tools if t["name"] != "object_import"]
    instructions = (REPO / "src/slic3r/GUI/JusPrin/AgentUI/src/projectInstructions.fixture.txt").read_text()
    return {"store": False, "parallel_tool_calls": True, "instructions": instructions, "tools": tools, "input": items}


def to_anthropic(body):
    """The same conversation in the Messages API's shape."""
    messages = []

    def add(role, block):
        if messages and messages[-1]["role"] == role:
            messages[-1]["content"].append(block)
        else:
            messages.append({"role": role, "content": [block]})

    for item in body["input"]:
        if item.get("type") == "function_call":
            add("assistant", {"type": "tool_use", "id": item["call_id"], "name": item["name"],
                              "input": json.loads(item["arguments"])})
        elif item.get("type") == "function_call_output":
            add("user", {"type": "tool_result", "tool_use_id": item["call_id"], "content": item["output"]})
        elif isinstance(item["content"], str):
            add(item["role"], {"type": "text", "text": item["content"]})
        else:
            for part in item["content"]:
                add(item["role"], {"type": "text", "text": part["text"]})
    return {"model": CLAUDE_MODEL, "max_tokens": 16000, "system": body["instructions"],
            "tools": [{"name": t["name"], "description": t["description"], "input_schema": t["parameters"]}
                      for t in body["tools"]],
            "messages": messages}


def post(url, headers, body):
    request = urllib.request.Request(url, data=json.dumps(body).encode(), method="POST",
                                     headers={"Content-Type": "application/json", **headers})
    for attempt in range(4):
        try:
            with urllib.request.urlopen(request, timeout=300) as response:
                return json.load(response)
        except urllib.error.HTTPError as error:
            if error.code not in (429, 500, 502, 503, 529) or attempt == 3:
                raise RuntimeError(f"HTTP {error.code}: {error.read().decode(errors='replace')[:600]}")
        time.sleep(2 ** attempt)


def send_openai(body):
    response = post("https://api.openai.com/v1/responses", {"Authorization": "Bearer " + os.environ["OPENAI_API_KEY"]},
                    {**body, "model": OPENAI_MODEL})
    text = "".join(part.get("text", "") for item in response["output"] if item["type"] == "message"
                   for part in item["content"])
    calls = [f"{item['name']} {item['arguments']}" for item in response["output"] if item["type"] == "function_call"]
    usage = response.get("usage", {})
    return text, calls, usage.get("input_tokens", 0), usage.get("output_tokens", 0)


def send_claude(body):
    response = post("https://api.anthropic.com/v1/messages",
                    {"x-api-key": os.environ["ANTHROPIC_API_KEY"], "anthropic-version": "2023-06-01"}, to_anthropic(body))
    text = "".join(block["text"] for block in response["content"] if block["type"] == "text")
    calls = [f"{block['name']} {json.dumps(block['input'])}" for block in response["content"] if block["type"] == "tool_use"]
    usage = response.get("usage", {})
    return text, calls, usage.get("input_tokens", 0), usage.get("output_tokens", 0)


def main():
    body = build()
    (OUT / "rebuilt-request.json").write_text(json.dumps(body, ensure_ascii=False, indent=1))
    text = json.dumps(body, ensure_ascii=False)
    print("bytes", len(text), "items", len(body["input"]), "tools", len(body["tools"]))
    for item in body["input"]:
        kind = item.get("type") or item["role"]
        detail = item.get("name") or (item["content"] if isinstance(item.get("content"), str) else "")
        print(" ", kind, str(detail)[:60].replace("\n", " "))
    print(body["input"][-8]["content"][0]["text"] if body["input"][-8].get("role") == "user" else "(workspace not at -8)")
    print("to_anthropic messages", len(to_anthropic(body)["messages"]))
    if len(sys.argv) < 3 or sys.argv[1] != "send":
        return
    runs = int(sys.argv[2])
    jobs = [("openai", OPENAI_MODEL, send_openai)] * runs + [("anthropic", CLAUDE_MODEL, send_claude)] * runs
    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
        futures = [(name, model, pool.submit(send, body)) for name, model, send in jobs]
        for name, model, future in futures:
            try:
                reply, calls, tokens_in, tokens_out = future.result()
                results.append({"provider": name, "model": model, "reply": reply, "calls": calls,
                                "inputTokens": tokens_in, "outputTokens": tokens_out,
                                "namesOrca": re.findall(r"\bOrca(?:Slicer)?\b", reply)})
            except Exception as error:  # one failed run should not lose the others' replies
                results.append({"provider": name, "model": model, "error": str(error)})
    (OUT / "replay-results.json").write_text(json.dumps(results, ensure_ascii=False, indent=1))
    for r in results:
        print("=" * 70)
        print(r["provider"], r["model"], {k: r.get(k) for k in ("inputTokens", "outputTokens", "namesOrca", "calls", "error")})
        print(r.get("reply", ""))
    print("total input", sum(r.get("inputTokens", 0) for r in results), "output", sum(r.get("outputTokens", 0) for r in results))


main()

